#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
# lib.sh, chargé plus bas, remplace ce confirm [y/N] par son confirm [o/N].
# shellcheck disable=SC2329
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
# Bibliothèque du wizard, identique d'un wizard à l'autre : cette fonction sert à d'autres.
# shellcheck disable=SC2329
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
# Bibliothèque du wizard, identique d'un wizard à l'autre : cette fonction sert à d'autres.
# shellcheck disable=SC2329
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
# Bibliothèque du wizard, identique d'un wizard à l'autre : cette fonction sert à d'autres.
# shellcheck disable=SC2329
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# La production ne lit ni n'écrit aucun fichier .env : les valeurs saisies ne vivent que
# dans ce processus, puis dans les secrets du Worker dezyn-api.
ENV_FILE=/dev/null

# lib.sh apporte les outils de production (Neon, wrangler, contrôles) ; son confirm [o/N]
# remplace celui de la bibliothèque du wizard.
# shellcheck source=lib.sh
source "$(dirname "$0")/lib.sh"

POLAR_DASHBOARD="https://polar.sh/dashboard"
POLAR_API="https://api.polar.sh/v1"
UUID_PATTERN='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

# polar_get PATH appelle l'API de production de Polar avec le jeton capturé, sans le
# passer en argument d'une commande.
polar_get() {
  curl --silent --show-error --max-time 15 --config - "$POLAR_API$1" <<< \
    "header = \"Authorization: Bearer $POLAR_ACCESS_TOKEN\""
}

require_tools() {
  local tool
  for tool in curl jq node gh; do
    command -v "$tool" > /dev/null 2>&1 || { echo "$tool est requis." >&2; exit 1; }
  done
  if ! gh auth status > /dev/null 2>&1; then
    echo "GitHub : lancer d'abord gh auth login" >&2
    exit 1
  fi
  require_neon_login
  if ! wrangler_api whoami 2> /dev/null | grep -q "You are logged in"; then
    echo "Cloudflare : lancer d'abord npx wrangler login dans apps/api" >&2
    exit 1
  fi
}

run_wizard() {

cd "$(dirname "$0")/../.."
require_terminal
require_tools

TOTAL_STAGES=9

banner "Polar : paiement de production de dezyn"

stage "Contrôles préalables"
say "Rien n'est écrit sur disque : le jeton et le secret du webhook ne vivent que dans ce"
say "processus, jusqu'à l'écriture des secrets du Worker dezyn-api (étape 8)."
say "Espaces en Team dont l'abonnement est terminé (rôle app, transaction en lecture seule) :"
project=$(preview_variable NEON_PROJECT_ID)
if ! ended=$(ended_team_spaces "$(neon_role_url "$project" "$PRODUCTION_BRANCH" app)"); then
  warn "lecture de la base de production impossible : relancer une fois Neon joignable."
  exit 1
fi
if [[ -n "$ended" ]]; then
  warn "ces espaces sont en Team sans abonnement en cours :"
  while IFS= read -r space; do note "    $space"; done <<< "$ended"
  warn "les repasser en Free (règle provisoire de #357) avant d'ouvrir le paiement."
  exit 1
fi
printf '  %s✓ aucun%s\n' "$GREEN" "$RESET"
if ! worker_secrets=$(worker_secret_names); then
  warn "lecture des secrets du Worker dezyn-api impossible : relancer une fois Cloudflare joignable."
  exit 1
fi
polar=$(polar_configuration "$worker_secrets")
note "Configuration Polar actuelle du Worker dezyn-api : $polar."
if [[ "$polar" != absente ]] && ! confirm "Le Worker a déjà des secrets POLAR_*. Les remplacer à l'étape 8 ?"; then
  exit 0
fi
pause

stage "Compte vendeur et versements"
say "La production de Polar est séparée du sandbox : compte, organisation et jetons à part."
open_url "$POLAR_DASHBOARD"
step "Se connecter avec le compte de production, puis créer l'organisation « dezyn »."
step "Settings : description du produit, site https://dezyn.dev, email de support vérifié."
step "Finance → Account : vérifier l'identité du propriétaire (KYC)."
step "Finance → Account : configurer le compte de versement (payout account)."
step "Une fois la checklist complète, soumettre la revue du compte (Finance → Account)."
note "Polar n'accepte de paiement qu'après l'approbation de la revue, jusqu'à 14 jours."
note "Les étapes suivantes se font pendant la revue ; le paiement réel (étape 9) attend"
note "l'approbation. Ctrl-C ici et relancer pnpm polar:production plus tard est sans risque."
pause "Revue soumise ? Entrée pour continuer"

stage "Devise et traitement des taxes"
say "Le plan Team se vend 34,99 € HT : prix en euros, taxe ajoutée au checkout."
open_url "$POLAR_DASHBOARD"
step "Settings de l'organisation, section Payments."
step "Default tax behavior : « Exclusive »."
step "Devise de paiement par défaut : EUR."
pause "Exclusive et EUR réglés ? Entrée pour continuer"

stage "Produit Team de production"
open_url "$POLAR_DASHBOARD"
step "Products → créer un nouveau produit."
step "Nom : Team."
step "Type : abonnement (recurring), facturé tous les mois (monthly)."
note "Le cycle de facturation ne change plus après la création."
step "Prix : Fixed price, 34.99, en EUR, taxe Exclusive (ou celle de l'organisation)."
step "N'ajouter aucun bénéfice (benefit), puis enregistrer le produit."
pause "Produit Team créé ? Entrée pour continuer"

stage "Jeton d'accès d'organisation"
open_url "$POLAR_DASHBOARD"
step "Settings → Access Tokens → Create token."
step "Nom : dezyn-production. Expiration : la plus longue proposée ; la noter pour la rotation."
step "Cocher exactement ces scopes, et aucun autre :"
note "    checkouts:write          créer le checkout d'un espace"
note "    customer_sessions:write  ouvrir le portail client du payeur"
note "    subscriptions:write      résilier en fin de période, révoquer un abonnement refusé"
note "    orders:read              lister les commandes d'un abonnement refusé"
note "    refunds:read             lister ses remboursements déjà faits"
note "    refunds:write            rembourser un abonnement refusé"
note "    products:read            relire le produit Team (étape 6 de ce wizard)"
note "Les webhooks se vérifient par leur secret : aucun scope webhooks n'est requis."
step "Créer le jeton, puis le copier tout de suite."
ask_secret POLAR_ACCESS_TOKEN "Coller le jeton d'accès :"
until [[ -n "$POLAR_ACCESS_TOKEN" ]]; do
  ask_secret POLAR_ACCESS_TOKEN "Coller le jeton d'accès :"
done
pause

stage "Identifiant du produit Team"
say "Produits de l'organisation de production, lus avec le jeton :"
if products=$(polar_get "/products/?is_archived=false") &&
  jq -e '.items' > /dev/null 2>&1 <<< "$products"; then
  jq -r '.items[] | "    \(.id)  \(.name)"' <<< "$products"
else
  warn "lecture impossible : vérifier le scope products:read, ou copier l'UUID depuis la page du produit."
fi
ask POLAR_TEAM_PRODUCT_ID "Identifiant du produit Team :"
until [[ "$POLAR_TEAM_PRODUCT_ID" =~ $UUID_PATTERN ]]; do
  warn "un identifiant de produit est un UUID en minuscules, par exemple 0b1c2d3e-…"
  ask POLAR_TEAM_PRODUCT_ID "Identifiant du produit Team :"
done
if product=$(polar_get "/products/$POLAR_TEAM_PRODUCT_ID") && jq -e '.id' > /dev/null 2>&1 <<< "$product"; then
  jq -r '"    \(.name) · \(if .is_recurring then "abonnement \(.recurring_interval)" else "paiement unique" end)",
    (.prices[] | "    \(.amount_type) \(.price_amount // "-") \(.price_currency // "")")' <<< "$product"
  note "Attendu : abonnement month, et un prix fixed 3499 eur (montant en centimes)."
  confirm "Le produit est-il conforme ?" || exit 1
else
  warn "produit illisible : vérifier le jeton, son scope products:read et l'identifiant."
  exit 1
fi
POLAR_SERVER=production
pause

stage "Webhook vers l'API de production"
say "L'API reçoit les webhooks de Polar sur sa route /webhooks/polar (ADR 0050)."
open_url "$POLAR_DASHBOARD"
step "Settings → Webhooks → Add Endpoint."
step "URL : $POLAR_WEBHOOK_URL"
step "Format : Raw."
step "Version d'API : 2027-01."
step "Secret : le laisser générer par Polar."
step "Événements, ceux que l'API traite et aucun autre : subscription.active,"
step "subscription.updated, subscription.past_due, subscription.canceled,"
step "subscription.uncanceled, subscription.revoked."
step "Créer l'endpoint, puis copier son secret."
note "Jusqu'à l'étape 8, l'API répond 503 : aucun checkout ne s'ouvre, donc aucun événement n'est perdu."
ask_secret POLAR_WEBHOOK_SECRET "Coller le secret du webhook :"
until [[ -n "$POLAR_WEBHOOK_SECRET" ]]; do
  ask_secret POLAR_WEBHOOK_SECRET "Coller le secret du webhook :"
done
pause

stage "Secrets du Worker dezyn-api"
say "Les quatre valeurs partent ensemble, en une seule version du Worker (wrangler secret bulk) :"
note "    POLAR_ACCESS_TOKEN     (masqué)"
note "    POLAR_WEBHOOK_SECRET   (masqué)"
note "    POLAR_TEAM_PRODUCT_ID  $POLAR_TEAM_PRODUCT_ID"
note "    POLAR_SERVER           $POLAR_SERVER"
note "L'API exige les quatre ou aucune : une partie seule rend chaque requête en erreur 500."
warn "Cette version est publiée aussitôt, avec le code déployé : le bouton de paiement"
warn "s'ouvre en production dès qu'elle est servie."
if ! confirm "Poser les quatre secrets sur le Worker dezyn-api maintenant ?"; then
  SKIPPED+=("secrets du Worker : relancer pnpm polar:production")
  finish
  exit 0
fi
POLAR_ACCESS_TOKEN=$POLAR_ACCESS_TOKEN POLAR_WEBHOOK_SECRET=$POLAR_WEBHOOK_SECRET \
  POLAR_TEAM_PRODUCT_ID=$POLAR_TEAM_PRODUCT_ID POLAR_SERVER=$POLAR_SERVER \
  polar_secrets_json | wrangler_api secret bulk --env="" > /dev/null
WRITTEN_SECRET+=("$POLAR_SECRETS (Worker dezyn-api)")
printf '  %s✓ set%s secrets POLAR_* du Worker dezyn-api\n' "$GREEN" "$RESET"
say "Vérification, une fois la version propagée :"
health="" webhook=""
for _ in 1 2 3 4 5 6; do
  sleep 5
  health=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 "$HEALTH_URL" || true)
  webhook=$(polar_webhook_status)
  [[ "$health" == 200 && "$webhook" == 401 ]] && break
done
if [[ "$health" == 200 && "$webhook" == 401 ]]; then
  printf '  %s✓ %s répond 200, %s refuse un événement non signé (401)%s\n' \
    "$GREEN" "$HEALTH_URL" "$POLAR_WEBHOOK_URL" "$RESET"
else
  warn "$HEALTH_URL répond $health, $POLAR_WEBHOOK_URL répond $webhook (401 attendu)."
  warn "Retirer les quatre secrets d'un coup referme le paiement :"
  note "    (cd apps/api && pnpm exec wrangler secret bulk --env=\"\" <<< '$(polar_removal_json)')"
  SKIPPED+=("vérifier l'API : pnpm prod:check")
fi
pause

stage "Premier paiement réel"
say "À faire une fois la revue du compte approuvée (étape 2)."
open_url "https://app.dezyn.dev"
step "Créer un espace de test, puis passer en Team depuis l'app avec une vraie carte."
step "Polar → Settings → Webhooks → l'endpoint : les livraisons répondent 200."
step "L'espace affiche le plan Team."
say "Dans Polar, révoquer d'abord, puis rembourser (ADR 0055) : l'espace ne reste jamais en Team"
say "après le remboursement."
step "1. Révoquer : Sales → Subscriptions → l'abonnement → ⋮ → Cancel Subscription → immédiatement."
step "   subscription.revoked est livré, répond 200, et l'espace repasse en Free."
step "2. Rembourser : Sales → Orders → la commande → Refund."
step "Vérifier : l'abonnement est « Canceled » dans Polar, la page « Plan » de l'espace affiche Free."
warn "Un remboursement seul laisse l'abonnement « Active » et l'espace en Team jusqu'à la fin de la période."
warn "« Cancel subscription » dans le portail client résilie en fin de période : l'espace reste en Team"
warn "jusqu'à cette date."
note "Puis poser l'alerte « refused polar subscription » : docs/runbooks/hebergement.md, section 7."
note "Contrôle complet : pnpm prod:check"
pause

finish
}

run_wizard "$@"; exit
